mapper.select:
select id, level, top_id as topId, parent_id as parentId, title, content, progress, status, dead_line as deadLine, sort_order as sortOrder, user_id as userId from mes_rec_goal
deleted_flag = 0 and user_id = #{param.userId}
and id = #{param.id}
and level = #{param.level}
and top_id in
#{id}
and title like concat('%', #{param.title}, '%')
and status = #{param.status}
and dead_line >= #{param.beginDeadLine}
and #{param.endDeadLine} > dead_line
order by sort_order asc
